import json
import csv
import copy

def solve():
    # Load instance
    with open('data/instance.txt', 'r') as f:
        lines = f.readlines()

    num_jobs, num_machines = map(int, lines[0].split())
    jobs = []
    line_idx = 1
    for j in range(num_jobs):
        num_ops = int(lines[line_idx])
        line_idx += 1
        job_ops = []
        for o in range(num_ops):
            parts = list(map(int, lines[line_idx].split()))
            line_idx += 1
            num_options = parts[0]
            options = {}
            for i in range(num_options):
                m = parts[1 + 2*i]
                d = parts[2 + 2*i]
                options[m] = d
            job_ops.append(options)
        jobs.append(job_ops)

    # Load downtime
    downtimes = []
    with open('data/downtime.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            downtimes.append({
                'machine': int(row['machine']),
                'start': int(row['start']),
                'end': int(row['end'])
            })

    # Load baseline
    with open('data/baseline_solution.json', 'r') as f:
        baseline_data = json.load(f)

    baseline_schedule = {}
    for item in baseline_data['schedule']:
        baseline_schedule[(item['job'], item['op'])] = item

    # Load policy
    with open('data/policy.json', 'r') as f:
        policy = json.load(f)

    max_machine_changes = policy['change_budget']['max_machine_changes']
    max_total_start_shift = policy['change_budget']['max_total_start_shift_L1']

    def is_machine_free(m, start, end, current_schedule):
        for dt in downtimes:
            if dt['machine'] == m:
                if not (end <= dt['start'] or start >= dt['end']):
                    return False
        for op_key, scheduled in current_schedule.items():
            if scheduled['machine'] == m:
                if not (end <= scheduled['start'] or start >= scheduled['end']):
                    return False
        return True

    def get_earliest_start(j, o, m, dur, current_schedule):
        prev_end = 0
        if o > 0:
            prev_end = current_schedule[(j, o-1)]['end']

        start = prev_end
        while True:
            end = start + dur
            if is_machine_free(m, start, end, current_schedule):
                return start
            # Jump to next possible time
            conflict_end = start + 1
            for dt in downtimes:
                if dt['machine'] == m:
                    if not (end <= dt['start'] or start >= dt['end']):
                        conflict_end = max(conflict_end, dt['end'])
            for op_key, scheduled in current_schedule.items():
                if scheduled['machine'] == m:
                    if not (end <= scheduled['start'] or start >= scheduled['end']):
                        conflict_end = max(conflict_end, scheduled['end'])
            start = conflict_end
            if start > 200: return 200 # Safety

    # Try different machine assignments to stay within machine_changes budget
    # Since only 4 changes allowed, we mostly use baseline machines.

    import itertools

    all_ops = []
    for j in range(num_jobs):
        for o in range(len(jobs[j])):
            all_ops.append((j, o))

    # We'll try to keep most machines. 
    # Let's try changing 0, 1, 2, 3, 4 machines.
    # But which ones? Probably the ones with downtime violations.
    violations = [(1, 1), (2, 0), (2, 2), (3, 1), (3, 2)] # From my earlier analysis

    # Actually, let's just try a greedy approach with a priority on baseline machines.

    def run_greedy(machine_assignment):
        current_schedule = {}
        available_ops = [(j, 0) for j in range(num_jobs)]

        while available_ops:
            # Pick the op that can start earliest
            candidates = []
            for j, o in available_ops:
                m = machine_assignment[(j, o)]
                dur = jobs[j][o][m]
                start = get_earliest_start(j, o, m, dur, current_schedule)
                candidates.append((start, j, o, m, dur))

            # Sort by start time, then baseline start time
            candidates.sort(key=lambda x: (x[0], baseline_schedule[(x[1], x[2])]['start']))

            start, j, o, m, dur = candidates[0]
            current_schedule[(j, o)] = {'job': j, 'op': o, 'machine': m, 'start': start, 'end': start + dur, 'dur': dur}

            available_ops.remove((j, o))
            if o + 1 < len(jobs[j]):
                available_ops.append((j, o+1))

        return current_schedule

    best_solution = None
    best_makespan = float('inf')

    # Try some machine assignments
    # 1. All baseline machines
    baseline_assignment = {(j, o): baseline_schedule[(j, o)]['machine'] for j, o in all_ops}

    # Try combinations of machine changes for the violating operations
    for r in range(min(len(violations), max_machine_changes) + 1):
        for combo in itertools.combinations(violations, r):
            assignment = baseline_assignment.copy()
            # For each op in combo, try an alternative machine
            # Since each op has only 2 options, there's only one alternative.
            for j, o in combo:
                options = list(jobs[j][o].keys())
                alt = [m for m in options if m != baseline_assignment[(j, o)]]
                if alt:
                    assignment[(j, o)] = alt[0]

            sol = run_greedy(assignment)

            # Check feasibility and budgets
            makespan = max(s['end'] for s in sol.values())
            total_shift = sum(abs(sol[k]['start'] - baseline_schedule[k]['start']) for k in all_ops)

            if total_shift <= max_total_start_shift:
                if makespan < best_makespan:
                    best_makespan = makespan
                    best_solution = sol
                    print(f"New best makespan: {best_makespan} (changes: {r}, shift: {total_shift})")

    if best_solution:
        res = {
            "status": "FEASIBLE",
            "makespan": int(best_makespan),
            "schedule": []
        }
        sorted_keys = sorted(best_solution.keys(), key=lambda x: (best_solution[x]['start'], best_solution[x]['job']))
        for k in sorted_keys:
            res['schedule'].append(best_solution[k])

        with open('output/solution.json', 'w') as f:
            json.dump(res, f, indent=2)

        with open('output/schedule.csv', 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['job', 'op', 'machine', 'start', 'end', 'dur'])
            for item in res['schedule']:
                writer.writerow([item['job'], item['op'], item['machine'], item['start'], item['end'], item['dur']])
    else:
        print("No solution found")

solve()

