import json
import csv
import itertools

def solve():
    with open('data/instance.txt', 'r') as f:
        lines = f.readlines()
    num_jobs, num_machines = map(int, lines[0].split())
    jobs = []
    line_idx = 1
    for j in range(num_jobs):
        num_ops = int(lines[line_idx])
        line_idx += 1
        job_ops = []
        for o in range(num_ops):
            parts = list(map(int, lines[line_idx].split()))
            line_idx += 1
            num_options = parts[0]
            options = {parts[1 + 2*i]: parts[2 + 2*i] for i in range(num_options)}
            job_ops.append(options)
        jobs.append(job_ops)

    downtimes = []
    with open('data/downtime.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            downtimes.append({'machine': int(row['machine']), 'start': int(row['start']), 'end': int(row['end'])})

    with open('data/baseline_solution.json', 'r') as f:
        baseline_schedule = {(item['job'], item['op']): item for item in json.load(f)['schedule']}

    with open('data/policy.json', 'r') as f:
        policy = json.load(f)
    max_machine_changes = policy['change_budget']['max_machine_changes']
    max_total_start_shift = policy['change_budget']['max_total_start_shift_L1']

    all_ops = sorted(baseline_schedule.keys())

    def get_makespan(assignment, machine_orders):
        current_schedule = {}
        # machine_orders is a dict: {m: [ (j, o), ... ]}
        # We need to schedule them while respecting job dependencies and machine orders.
        # This is like a DAG.

        # We can use a simple simulation.
        scheduled_count = 0
        machine_pointers = {m: 0 for m in range(num_machines)}

        while scheduled_count < len(all_ops):
            progress = False
            for m in range(num_machines):
                if machine_pointers[m] < len(machine_orders[m]):
                    j, o = machine_orders[m][machine_pointers[m]]

                    # Can we schedule (j, o) now?
                    # Check job dependency
                    prev_end = 0
                    if o > 0:
                        if (j, o-1) in current_schedule:
                            prev_end = current_schedule[(j, o-1)]['end']
                        else:
                            continue # Wait for prev op

                    # Check machine dependency
                    m_prev_end = 0
                    if machine_pointers[m] > 0:
                        prev_j, prev_o = machine_orders[m][machine_pointers[m]-1]
                        m_prev_end = current_schedule[(prev_j, prev_o)]['end']

                    start = max(prev_end, m_prev_end)
                    dur = jobs[j][o][m]

                    # Check downtime
                    while True:
                        end = start + dur
                        conflict = False
                        for dt in downtimes:
                            if dt['machine'] == m and not (end <= dt['start'] or start >= dt['end']):
                                start = dt['end']
                                conflict = True
                                break
                        if not conflict: break

                    current_schedule[(j, o)] = {'job': j, 'op': o, 'machine': m, 'start': start, 'end': start + dur, 'dur': dur}
                    machine_pointers[m] += 1
                    scheduled_count += 1
                    progress = True

            if not progress:
                return float('inf'), None # Deadlock

        return max(s['end'] for s in current_schedule.values()), current_schedule

    baseline_assignment = {k: v['machine'] for k, v in baseline_schedule.items()}

    # Try baseline assignment first
    m_ops = {m: [] for m in range(num_machines)}
    for k, m in baseline_assignment.items():
        m_ops[m].append(k)

    # Permutations
    import itertools
    best_ms, best_sol = float('inf'), None

    # Limit permutations to avoid too much time
    # Actually, 120 * 24 * 24 is fine.
    m_perms = {m: list(itertools.permutations(m_ops[m])) for m in range(num_machines)}

    print(f"Total combinations: {len(m_perms[0]) * len(m_perms[1]) * len(m_perms[2])}")

    for p0 in m_perms[0]:
        for p1 in m_perms[1]:
            for p2 in m_perms[2]:
                ms, sol = get_makespan(baseline_assignment, {0: p0, 1: p1, 2: p2})
                if ms < best_ms:
                    shift = sum(abs(sol[k]['start'] - baseline_schedule[k]['start']) for k in all_ops)
                    if shift <= max_total_start_shift:
                        best_ms, best_sol = ms, sol
                        print(f"New best: {best_ms}")
                if best_ms <= 30: break # Good enough
            if best_ms <= 30: break
        if best_ms <= 30: break

    # If still not < 36, try a few other machine assignments
    if best_ms >= 36:
        # Try changing one machine
        for op_to_change in all_ops:
            opts = list(jobs[op_to_change[0]][op_to_change[1]].keys())
            alt_m = [m for m in opts if m != baseline_assignment[op_to_change]][0]
            new_ass = baseline_assignment.copy()
            new_ass[op_to_change] = alt_m

            new_m_ops = {m: [] for m in range(num_machines)}
            for k, m in new_ass.items(): new_m_ops[m].append(k)
            new_m_perms = {m: list(itertools.permutations(new_m_ops[m])) for m in range(num_machines)}

            for p0 in new_m_perms[0][:60]: # Limit search
                for p1 in new_m_perms[1][:24]:
                    for p2 in new_m_perms[2][:24]:
                        ms, sol = get_makespan(new_ass, {0: p0, 1: p1, 2: p2})
                        if ms < best_ms:
                            shift = sum(abs(sol[k]['start'] - baseline_schedule[k]['start']) for k in all_ops)
                            if shift <= max_total_start_shift:
                                best_ms, best_sol = ms, sol
                                print(f"New best (alt): {best_ms}")

    if best_sol:
        res = {"status": "FEASIBLE", "makespan": int(best_ms), 
               "schedule": sorted(best_sol.values(), key=lambda x: (x['start'], x['job']))}
        with open('output/solution.json', 'w') as f: json.dump(res, f, indent=2)
        with open('output/schedule.csv', 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['job', 'op', 'machine', 'start', 'end', 'dur'])
            for item in res['schedule']:
                writer.writerow([item['job'], item['op'], item['machine'], item['start'], item['end'], item['dur']])
    else: print("No solution")

